#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Stripe go-live for dfg.rocks (task ts-c53b8f). Two phases: test keys and a purchase on the staged
# copy, then live keys just before the release. The staged copy and production read the same
# OpenBao path (secret/data/dfg-rocks), so after stage 10 the staged copy runs on live keys too
# (server-ansible task ts-7e43c4). Delete this script once go-live is done.

cd "$(git rev-parse --show-toplevel)"

TOTAL_STAGES=11
WEBHOOK_EVENTS="customer.subscription.created,customer.subscription.updated,customer.subscription.deleted"
STRIPE_KEYS=(stripe_secret_key stripe_webhook_secret stripe_price_monthly stripe_price_annual)
WRITTEN_KV=()

# set_kv KEY VALUE stores one key at secret/data/dfg-rocks with the ops login token. An empty
# value keeps what OpenBao already holds, so a re-run can skip a key.
set_kv() {
  local key="$1" value="$2"
  if [[ -z "$value" ]]; then
    note "kept the stored $key"
    return
  fi
  if printf '%s' "$value" | ops secret set "$key" >/dev/null; then
    WRITTEN_KV+=("$key")
    printf '  %s✓ stored%s %s in OpenBao\n' "$GREEN" "$RESET" "$key"
  else
    SKIPPED+=("OpenBao key $key (run: ops secret set $key)")
    warn "could not store $key; run 'ops login' and set it with: ops secret set $key"
  fi
}

banner "Stripe go-live for dfg.rocks"

stage "Tools: ops login and the Stripe CLI"
say "OpenBao takes secrets only with a fresh ops login, and the staged test purchase"
say "needs the Stripe CLI to forward webhooks to the tailnet-only staged copy."
step "If 'ops login' is more than 10 hours old, run it now in another terminal."
if ! command -v stripe >/dev/null 2>&1; then
  warn "The Stripe CLI is not installed."
  open_url "https://docs.stripe.com/stripe-cli"
  step "Install it (Arch: the AUR package stripe-cli), then come back."
  pause "Press Enter when 'stripe --version' works"
  command -v stripe >/dev/null 2>&1 || { warn "stripe is still not on PATH; stopping."; exit 1; }
fi
note "$(stripe --version)"
pause

stage "cartridge.json: the four Stripe secrets"
say "The server reads four Stripe settings from OpenBao. cartridge.json must name them"
say "before 'ops secret set' accepts them. This edits the file locally; stage 7 commits it."
if jq -e '[.services[0].secrets[] | select(._tag == "KvSecret") | .key] | index("stripe_secret_key")' cartridge.json >/dev/null; then
  note "cartridge.json already names the Stripe secrets."
else
  tmp=$(mktemp)
  jq '.services[0].secrets += [
        {"_tag":"KvSecret","path":"secret/data/dfg-rocks","key":"stripe_secret_key","env":"STRIPE_SECRET_KEY"},
        {"_tag":"KvSecret","path":"secret/data/dfg-rocks","key":"stripe_webhook_secret","env":"STRIPE_WEBHOOK_SECRET"},
        {"_tag":"KvSecret","path":"secret/data/dfg-rocks","key":"stripe_price_monthly","env":"STRIPE_PRICE_MONTHLY"},
        {"_tag":"KvSecret","path":"secret/data/dfg-rocks","key":"stripe_price_annual","env":"STRIPE_PRICE_ANNUAL"}
      ]' cartridge.json > "$tmp" && mv "$tmp" cartridge.json
  printf '  %s✓ added%s %s to cartridge.json\n' "$GREEN" "$RESET" "${STRIPE_KEYS[*]}"
fi
warn "Do not push develop until stage 7: a deploy fails while a named secret is unset."
pause

stage "Test mode: the product and its two prices"
open_url "https://dashboard.stripe.com/test/products/create"
step "Name the product (for example 'dfg.rocks subscription')."
step "Add a recurring price, billing period Monthly, with the monthly amount."
step "Add a second recurring price, billing period Yearly, with the annual amount."
step "For each price, choose whether tax is included in the price or added on top (Stripe Tax needs one)."
step "Save. Open each price: its ID (price_...) is at the top right."
ask TEST_PRICE_MONTHLY "Paste the monthly price ID (price_...):"
ask TEST_PRICE_ANNUAL "Paste the annual price ID (price_...):"

stage "Test mode: Customer Portal and Stripe Tax"
say "Manage subscription opens the Customer Portal, and checkout asks Stripe Tax for the tax."
open_url "https://dashboard.stripe.com/test/settings/billing/portal"
step "Turn on: cancel subscriptions, update payment methods, view invoice history."
step "Under switching plans, add the product, so a customer can move between monthly and annual."
step "Save."
pause "Press Enter when the portal is saved"
open_url "https://dashboard.stripe.com/test/settings/tax"
step "Set the head office address and the default tax category for the product."
step "Add a tax registration for each place the studio must collect tax."
pause "Press Enter when Stripe Tax is set up"

stage "Test mode: secret key and prices into OpenBao"
open_url "https://dashboard.stripe.com/test/apikeys"
step "On the Secret key row, click Reveal test key and copy it (sk_test_...)."
ask_secret TEST_SECRET_KEY "Paste the test secret key (hidden; Enter keeps the stored one):"
set_kv stripe_secret_key "$TEST_SECRET_KEY"
set_kv stripe_price_monthly "$TEST_PRICE_MONTHLY"
set_kv stripe_price_annual "$TEST_PRICE_ANNUAL"

stage "Test mode: the webhook secret from the Stripe CLI"
say "Stripe cannot reach the tailnet-only staged copy, so the Stripe CLI on this machine"
say "receives the events and forwards them. Its signing secret is the webhook secret."
step "Find the staged copy's address in 'ops dash' (the dfg-rocks-server staged route)."
ask STAGED_URL "Paste the staged URL (https://..., no trailing slash):"
STAGED_URL="${STAGED_URL%/}"
step "The CLI logs in through the browser; approve it there."
stripe login
WEBHOOK_SECRET_TEST=$(stripe listen --print-secret)
set_kv stripe_webhook_secret "$WEBHOOK_SECRET_TEST"

stage "Deploy the staged copy"
say "Commit cartridge.json, then push develop: the push to cynic deploys the staged copy."
if git diff --quiet -- cartridge.json; then
  note "cartridge.json has no uncommitted change."
elif confirm "Commit cartridge.json now (a local commit)?"; then
  git commit -q -m "build(deploy): give the server the Stripe settings from OpenBao" -- cartridge.json
  printf '  %s✓ committed%s cartridge.json\n' "$GREEN" "$RESET"
fi
step "Run: git push origin develop && git push cynic develop"
step "Wait until 'ops dash' shows the staged copy healthy."
pause "Press Enter when the staged copy is healthy"

stage "Test purchase on the staged copy"
step "In another terminal, keep this running for the whole stage:"
note "    stripe listen --events $WEBHOOK_EVENTS --forward-to $STAGED_URL/api/stripe/webhook"
open_url "$STAGED_URL/pricing"
step "Check both plans show the amounts you set."
step "Sign in as a test account that has no family, or is its family's billing contact."
step "Subscribe to Monthly. Pay with card 4242 4242 4242 4242, any future date, any CVC."
step "The success page must say you are subscribed (the listen terminal shows a 200)."
step "Open settings: the plan and its renewal date show. Click Manage subscription."
step "In the portal, cancel the subscription and return. Settings now say it ends on a date."
if ! confirm "Did every check pass?"; then
  warn "Stop here. Keep the test keys, and send the failing step and the listen output to the coordinator."
  exit 1
fi

stage "Live mode: activate, then Tax, Portal and the product"
open_url "https://dashboard.stripe.com/"
step "Leave test mode. Follow the banner to activate payments: business details and bank account."
pause "Press Enter when Stripe says the account can take live payments"
open_url "https://dashboard.stripe.com/test/products"
step "Open the product and use 'Copy to live mode' (or create it again in live mode)."
step "In live mode, open each price and copy its ID."
ask LIVE_PRICE_MONTHLY "Paste the live monthly price ID (price_...):"
ask LIVE_PRICE_ANNUAL "Paste the live annual price ID (price_...):"
open_url "https://dashboard.stripe.com/settings/billing/portal"
step "Repeat the portal settings from stage 4 in live mode, and save."
open_url "https://dashboard.stripe.com/settings/tax"
step "Repeat the Stripe Tax settings from stage 4 in live mode."
pause "Press Enter when the live portal and Tax are set up"

stage "Live mode: webhook and keys into OpenBao"
open_url "https://dashboard.stripe.com/webhooks/create"
step "Endpoint URL: https://dfg.rocks/api/stripe/webhook"
step "Events: customer.subscription.created, customer.subscription.updated, customer.subscription.deleted"
step "Save, then reveal the signing secret (whsec_...)."
ask_secret LIVE_WEBHOOK_SECRET "Paste the live signing secret (hidden):"
open_url "https://dashboard.stripe.com/apikeys"
step "Reveal the live secret key (sk_live_...) and copy it."
ask_secret LIVE_SECRET_KEY "Paste the live secret key (hidden):"
warn "From here the staged copy also runs on live keys: a purchase there charges a real card."
if confirm "Store the four live values in OpenBao now?"; then
  set_kv stripe_secret_key "$LIVE_SECRET_KEY"
  set_kv stripe_webhook_secret "$LIVE_WEBHOOK_SECRET"
  set_kv stripe_price_monthly "$LIVE_PRICE_MONTHLY"
  set_kv stripe_price_annual "$LIVE_PRICE_ANNUAL"
else
  SKIPPED+=("live Stripe values: re-run this wizard and store them at stage 10")
fi

stage "Release and check production"
step "From a clean checkout on main, run: ops promote"
step "Run the push command it prints (a push of main to cynic releases)."
step "If the promote committed a migration: on develop, run git merge --ff-only main"
pause "Press Enter when 'ops dash' shows production healthy"
open_url "https://dfg.rocks/pricing"
step "Check both plans show the live amounts."
note "Optional: buy with a real card, check settings, then refund and cancel it in the dashboard."
pause

finish
(( ${#WRITTEN_KV[@]} )) && note "stored ${#WRITTEN_KV[@]} OpenBao key(s): ${WRITTEN_KV[*]}"
note "Mark the task done: tasks done ts-c53b8f"
